stepxmp.codeblock:
:root {
  --opend-accent: #1f5fbf;      /* brand colour: links, highlights, focus */
  --opend-text: #14213d;
  --opend-muted: #52607a;       /* short descriptions, secondary text */
  --opend-surface: #ffffff;     /* page background */
  --opend-surface-alt: #f2f5fa; /* code, table headers, the open menu */
  --opend-border: #d9e0ea;
  --opend-warn: #b45309;        /* warning, caution and restriction notes */
  --opend-danger: #b3261e;      /* danger notes */
  --opend-info: #2457c5;        /* plain notes */
  --opend-cond: #7c3aed;        /* condition markers in the staff view */
  --opend-font: system-ui, sans-serif;
  --opend-mono: ui-monospace, Menlo, monospace;
}
@media (prefers-color-scheme: dark) {
  :root { --opend-accent: #7fb0ff; --opend-surface: #10151d; --opend-text: #e6ebf2; }
}
